    {"id": "a4_21", "level": 4, "term": "정선", "definition": "중국 산수를 모방하던 관념산수화를 탈피해 우리 강산을 직접 보고 그린 진경산수화의 개척자."},
    {"id": "a4_22", "level": 4, "term": "김홍도", "definition": "서당, 씨름, 대장간 등 서민들의 일상생활을 살아있는 해학과 역동적 필선으로 포착한 천재 화가."},
    {"id": "a4_23", "level": 4, "term": "서당도", "definition": "훈장님 앞에서 눈물을 훔치는 학동과 이를 키득거리며 웃는 친구들을 해학적으로 포착함."},
    {"id": "a4_24", "level": 4, "term": "씨름도", "definition": "원형 구도 속에 씨름꾼의 팽팽한 힘겨루기와 둘러앉은 구경꾼들의 열띤 표정을 박진감 있게 묘사함."},
    {"id": "a4_25", "level": 4, "term": "신윤복", "definition": "조선 후기 양반과 기녀의 풍류와 남녀 간의 은밀한 애정을 화려하고 세련된 채색으로 그린 풍속화가."},
    {"id": "a4_26", "level": 4, "term": "미인도", "definition": "신윤복이 얹은머리에 삼회장저고리를 입고 옷고름을 쥐고 있는 조선 여인의 자태를 섬세하게 그림."},
    {"id": "a4_27", "level": 4, "term": "단오풍정", "definition": "단오날 창포물에 머리 감는 여인들과 그네 타는 여인을 바위 틈에서 훔쳐보는 동자승들을 유쾌하게 그림."},
    {"id": "a4_28", "level": 4, "term": "김정희", "definition": "제주도 유배 시절 제자 이상적의 변함없는 의리에 감동하여 추운 겨울 소나무를 그린 '세한도' 화가."},
    {"id": "a4_29", "level": 4, "term": "세한도", "definition": "'날이 차가워진 뒤에야 소나무와 잣나무가 시들지 않음을 안다'는 지조를 마른 붓질로 승화시킨 국보."},
    {"id": "a4_30", "level": 4, "term": "문인화", "definition": "직업 화가가 아닌 사대부 문인들이 학문과 인격을 닦으며 사군자나 산수에 마음을 담아 그린 그림."},
    {"id": "a4_31", "level": 4, "term": "사군자", "definition": "군자의 고결한 인품에 비유되는 매화(봄), 난초(여름), 국화(가을), 대나무(겨울)의 네 식물."},

    # Lv.5 (+21)
    {"id": "a5_11", "level": 5, "term": "보티첼리", "definition": "피렌체 메디치가의 후원을 받아 시적이고 우아한 곡선으로 '비너스의 탄생'을 그린 르네상스 화가."},
    {"id": "a5_12", "level": 5, "term": "비너스의탄생", "definition": "조개껍데기 위에 선 미의 여신 비너스가 서풍 제피로스의 바람을 타고 해변에 닿는 명화."},
    {"id": "a5_13", "level": 5, "term": "스푸마토", "definition": "물체의 윤곽선을 연기처럼 흐릿하게 번지게 처리하여 자연스러운 음영과 신비감을 주는 기법."},
    {"id": "a5_14", "level": 5, "term": "최후의만찬", "definition": "다빈치가 밀라노 수도원 식당 벽에 '너희 중 하나가 나를 배신할 것이다'라는 순간의 동요를 완벽한 원근법으로 그림."},
    {"id": "a5_15", "level": 5, "term": "천지창조", "definition": "미켈란젤로가 시스티나 성당 천장에 누워 4년간 혼자 아담에게 생명의 불꽃을 건네는 신을 그림."},
    {"id": "a5_16", "level": 5, "term": "피에타", "definition": "십자가에서 내려진 죽은 예수를 무릎에 안고 비통한 슬픔을 고요하게 삭이는 성모 마리아 대리석 조각."},
    {"id": "a5_17", "level": 5, "term": "다비드상", "definition": "골리앗을 노려보며 투석구를 어깨에 멘 소년 다윗의 긴장된 근육과 영웅적 투지를 완벽한 비례로 조각함."},
    {"id": "a5_18", "level": 5, "term": "아테네학당", "definition": "라파엘로가 바티칸 궁전 벽에 플라톤, 아리스토텔레스 등 고대 그리스 철학자들을 한 공간에 모아 그림."},
    {"id": "a5_19", "level": 5, "term": "바로크미술", "definition": "르네상스의 정적인 균형을 깨고 강렬한 명암 대비와 극적인 역동성, 화려한 감정을 폭발시킨 사조."},
    {"id": "a5_20", "level": 5, "term": "카라바조", "definition": "어두운 배경 속에 한 줄기 강렬한 빛을 비추는 키아로스쿠로 명암법으로 성경 장면을 실감 나게 그린 천재."},
    {"id": "a5_21", "level": 5, "term": "명암대조법", "definition": "어둠과 극적인 스포트라이트 조명을 대비시켜 인물의 극적 감정과 긴장감을 증폭시키는 기법(키아로스쿠로)."},
    {"id": "a5_22", "level": 5, "term": "렘브란트", "definition": "빛과 어둠의 마술사로 불리며 '야간순찰(야경)'과 수십 점의 영혼 어린 자화상을 남긴 네덜란드 거장."},
    {"id": "a5_23", "level": 5, "term": "야경", "definition": "암스테르담 민병대원들의 출동 순간을 정적인 기념사진이 아닌 역동적인 드라마로 연출한 렘브란트 걸작."},
    {"id": "a5_24", "level": 5, "term": "베르메르", "definition": "창문으로 스며드는 부드러운 아침 햇살 속에 일상적인 여인의 고요한 순간을 포착한 네덜란드 화가."},
    {"id": "a5_25", "level": 5, "term": "진주귀걸이", "definition": "터번을 쓴 소녀가 어둠 속에서 고개를 돌려 반짝이는 눈동자와 진주 귀걸이를 응시하는 베르메르의 수작."},
    {"id": "a5_26", "level": 5, "term": "루벤스", "definition": "풍만한 육체미와 소용돌이치는 역동적 구성, 눈부신 색채로 가톨릭 교회의 장엄함을 표현한 바로크 거장."},
    {"id": "a5_27", "level": 5, "term": "벨라스케스", "definition": "스페인 궁정화가로서 국왕 부부와 마르가리타 공주, 자신을 복합적 시선으로 담아낸 '시녀들'의 화가."},
    {"id": "a5_28", "level": 5, "term": "시녀들", "definition": "보는 사람과 그려지는 대상의 위치를 뒤흔들며 현대 예술 이론가들에게 수많은 영감을 준 명화(라스 메니나스)."},
    {"id": "a5_29", "level": 5, "term": "로코코미술", "definition": "18세기 프랑스 귀족들의 사치스럽고 우아하며 조개껍데기 곡선과 파스텔톤 색채가 넘치는 궁정 미술."},
    {"id": "a5_30", "level": 5, "term": "와토", "definition": "우아한 귀족들이 사랑의 섬 시테라로 소풍을 떠나는 로코코 페트 갈랑트(우아한 연회)의 창시자."},
    {"id": "a5_31", "level": 5, "term": "프라고나르", "definition": "화려한 정원에서 그네를 타는 여인과 숨어서 훔쳐보는 연인의 경쾌한 밀회를 그린 로코코 화가."},

    # Lv.6 (+21)
    {"id": "a6_11", "level": 6, "term": "신고전주의", "definition": "로코코의 경박함에 반발하여 고대 그리스·로마의 엄격한 도덕성, 균형, 명확한 데생을 부활시킨 사조."},
    {"id": "a6_12", "level": 6, "term": "다비드", "definition": "프랑스 혁명과 나폴레옹 제정의 수석 화가로서 '호라티우스 형제의 맹세', '마라의 죽음'을 그린 거장."},
    {"id": "a6_13", "level": 6, "term": "마라의죽음", "definition": "혁명 지도자 마라가 욕조에서 반혁명파 여인에게 암살당한 순교의 순간을 정결한 비극으로 묘사함."},
    {"id": "a6_14", "level": 6, "term": "앵그르", "definition": "신고전주의의 완벽한 데생과 유려한 곡선미를 지키며 '오달리스크', '샘'을 그린 다비드의 수제자."},
    {"id": "a6_15", "level": 6, "term": "낭만주의미술", "definition": "차가운 이성 대신 격정적인 감정, 상상력, 이국적 취향과 비극적 영웅주의를 화폭에 담은 19세기 사조."},
    {"id": "a6_16", "level": 6, "term": "들라크루아", "definition": "프랑스 7월 혁명의 열기를 삼색기를 든 자유의 여신으로 표현한 낭만주의 회화의 기수."},
    {"id": "a6_17", "level": 6, "term": "자유의여신", "definition": "들라크루아가 그린 '민중을 이끄는 자유의 여신'으로 바리케이드 위의 시민 혁명을 상징하는 걸작."},
    {"id": "a6_18", "level": 6, "term": "제리코", "definition": "실제 난파선 조난자들의 처절한 생존 투쟁을 대형 캔버스에 박진감 있게 고발한 '메두사호의 뗏목' 화가."},
    {"id": "a6_19", "level": 6, "term": "고야", "definition": "스페인을 침략한 나폴레옹 군대의 잔혹한 민간인 총살을 고발한 '1808년 5월 3일'을 남긴 화가."},
    {"id": "a6_20", "level": 6, "term": "사실주의미술", "definition": "신화나 영웅 대신 '천사를 보여주면 천사를 그리겠다'며 가난한 노동자와 현실을 미화 없이 직시함."},
    {"id": "a6_21", "level": 6, "term": "쿠르베", "definition": "사실주의의 거두로서 '돌 깨는 사람들', '오르낭의 매장'을 통해 아카데미의 위선을 폭로함."},
    {"id": "a6_22", "level": 6, "term": "밀레", "definition": "바르비종 숲에서 농민들의 신성하고 경건한 노동의 가치를 '이삭 줍는 여인들', '만종'으로 승화시킴."},
    {"id": "a6_23", "level": 6, "term": "만종", "definition": "하루 일과를 마친 황혼녘 들판에서 부부가 삼종기도 종소리에 맞춰 감사 기도를 올리는 평화로운 명화."},
    {"id": "a6_24", "level": 6, "term": "이삭줍기", "definition": "추수가 끝난 황량한 밭에서 허리를 굽혀 떨어진 이삭을 줍는 세 가난한 농촌 여인의 숭고한 침묵."},
    {"id": "a6_25", "level": 6, "term": "바르비종파", "definition": "퐁텐블로 숲 바르비종 마을에 모여 야외에서 직접 자연의 빛과 농민의 삶을 스케치한 풍경화가들."},
    {"id": "a6_26", "level": 6, "term": "로댕", "definition": "근대 조각의 아버지로 불리며 거친 청동 표면에 고뇌하는 인간의 영혼을 새긴 '생각하는 사람'의 거장."},
    {"id": "a6_27", "level": 6, "term": "생각하는사람", "definition": "단테의 신곡 지옥편에서 영감을 얻은 '지옥의 문' 상단에서 깊은 인간적 고뇌에 잠긴 나체 남성 조각."},
    {"id": "a6_28", "level": 6, "term": "클림트", "definition": "빈 분리파를 이끌며 황금빛 모자이크 장식과 에로티시즘으로 영원한 사랑을 그린 '키스'의 화가."},
    {"id": "a6_29", "level": 6, "term": "키스", "definition": "화려한 금박 옷을 입은 남녀가 꽃밭 벼랑 끝에서 황홀한 입맞춤에 빠져드는 세기말 빈 미술의 대표작."},
    {"id": "a6_30", "level": 6, "term": "에곤실레", "definition": "뒤틀린 육체와 신경질적인 선으로 죽음의 공포와 적나라한 인간의 본능을 표출한 천재 화가."},
    {"id": "a6_31", "level": 6, "term": "아르누보", "definition": "식물 덩굴과 꽃, 파도의 유기적인 곡선 모티프를 건축, 공예, 가구에 적용한 새로운 예술 양식."},

    # Lv.7 (+21)
    {"id": "a7_11", "level": 7, "term": "인상주의", "definition": "작업실을 벗어나 야외에서 시시각각 변화하는 태양 빛과 색채의 찰나적 인상을 포착한 혁명적 사조."},
    {"id": "a7_12", "level": 7, "term": "에두아르마네", "definition": "'풀밭 위의 점심식사'와 '올랭피아'로 원근법과 고전적 이상화를 부수고 현대 회화의 문을 연 선구자."},
    {"id": "a7_13", "level": 7, "term": "클로드모네", "definition": "'인상, 일출'로 인상파라는 이름을 낳았으며 지베르니 연못에서 말년까지 '수련' 연작을 그린 빛의 화가."},
    {"id": "a7_14", "level": 7, "term": "인상일출", "definition": "르아브르 항구의 안개 낀 아침 바다 위로 붉은 해가 솟아오르는 빛의 순간적 인상을 거친 붓터치로 그림."},
    {"id": "a7_15", "level": 7, "term": "수련", "definition": "모네가 시력을 잃어가면서도 물 위에 비친 빛과 구름, 수련의 반영을 거대한 파노라마 화폭에 담은 걸작."},
    {"id": "a7_16", "level": 7, "term": "르누아르", "definition": "따스한 햇살 아래 파리 시민들의 행복한 여가를 눈부신 색채로 찬미한 '물랭 드 라 갈레트'의 화가."},
    {"id": "a7_17", "level": 7, "term": "드가", "definition": "발레 연습실의 무용수들과 경마장의 경주마들을 사진 같은 순간 포착과 과감한 사선 구도로 그림."},
    {"id": "a7_18", "level": 7, "term": "신인상주의", "definition": "인상파의 직관적 감각을 넘어 광학 색채 이론에 바탕을 두고 순색의 작은 점을 찍어 형태를 구성함."},
    {"id": "a7_19", "level": 7, "term": "조르주쇠라", "definition": "물감을 팔레트에서 섞지 않고 캔버스 위에 원색의 점을 찍어 망막에서 혼색되게 만든 점묘법의 창시자."},
    {"id": "a7_20", "level": 7, "term": "점묘법", "definition": "수백만 개의 작은 색점을 찍어 보는 이의 눈 속에서 색이 섞여 밝고 눈부신 빛의 진동을 느끼게 하는 기법."},
    {"id": "a7_21", "level": 7, "term": "그랑드자트섬", "definition": "쇠라가 센강의 섬에서 일요일 오후를 즐기는 파리 시민들의 정적인 조화를 2년간 점묘로 완성한 대표작."},
    {"id": "a7_22", "level": 7, "term": "후기인상주의", "definition": "빛의 찰나적 인상에만 머물지 않고 화가의 주관적 내면과 견고한 형태, 원시적 생명력을 탐구한 거장들."},
    {"id": "a7_23", "level": 7, "term": "반고흐", "definition": "타오르는 붓터치와 강렬한 노란색으로 인간의 고독과 영혼의 열정을 쏟아낸 '별이 빛나는 밤'의 비운의 천재."},
    {"id": "a7_24", "level": 7, "term": "별이빛나는밤", "definition": "생레미 정신병원 요양 중 소용돌이치는 밤하늘의 은하수와 별빛, 삼나무를 격렬한 붓질로 그린 걸작."},
    {"id": "a7_25", "level": 7, "term": "해바라기", "definition": "노란색의 무한한 변주를 통해 고흐가 아를의 노란 집에서 고갱을 기다리며 그린 불꽃같은 정물화."},
    {"id": "a7_26", "level": 7, "term": "폴고갱", "definition": "문명을 버리고 남태평양 타히티섬으로 건너가 원시적 생명력과 강렬한 원색 면으로 신비로운 화풍을 개척함."},
    {"id": "a7_27", "level": 7, "term": "폴세잔", "definition": "'자연의 모든 형태는 원통, 구, 원뿔로 이루어져 있다'며 형태의 본질을 탐구해 현대 미술의 아버지가 됨."},
    {"id": "a7_28", "level": 7, "term": "생빅투아르산", "definition": "세잔이 고향 엑상프로방스의 바위산을 수십 번 반복해서 그리며 다시점과 기하학적 면 분할을 실험함."},
    {"id": "a7_29", "level": 7, "term": "툴루즈로트레크", "definition": "물랭 루주 카바레의 무용수와 밤문화를 과감한 윤곽선과 평면적 색채의 현대적 포스터 아트로 완성함."},
    {"id": "a7_30", "level": 7, "term": "자포니즘", "definition": "일본의 우키요에 채색 목판화가 인상파 화가들의 평면 구성과 과감한 구도에 지대한 영향을 미친 현상."},
    {"id": "a7_31", "level": 7, "term": "우키요에", "definition": "에도 시대 서민들의 풍속, 가부키 배우, 기녀, 명승지를 다색 목판화로 대량 인쇄한 일본 전통 판화."},

    # Lv.8 (+21)
    {"id": "a8_11", "level": 8, "term": "야수파", "definition": "사물의 원래 색채를 파괴하고 화가의 감정을 분출하는 거칠고 순수한 원색을 캔버스에 쏟아낸 사조."},
    {"id": "a8_12", "level": 8, "term": "앙리마티스", "definition": "야수파의 리더로서 색채의 해방을 이끌고 말년에는 종이오리기(데쿠파주)로 단순하고 순수한 조화를 이룸."},
    {"id": "a8_13", "level": 8, "term": "붉은색의조화", "definition": "벽지와 식탁보의 경계를 허물고 온 화면을 붉은 단색으로 채워 색채 자체의 리듬을 찬미한 마티스 명작."},
    {"id": "a8_14", "level": 8, "term": "입체파", "definition": "사물을 단 하나의 고정된 시점으로 보지 않고 여러 각도에서 해체한 뒤 기하학적으로 재조합한 큐비즘."},
    {"id": "a8_15", "level": 8, "term": "피카소", "definition": "'아비뇽의 처녀들'과 '게르니카'로 미술사의 패러다임을 바꾼 20세기 최고의 혁신적 거장."},
    {"id": "a8_16", "level": 8, "term": "아비뇽의처녀들", "definition": "다섯 여성의 인체를 기하학적 다면체와 아프리카 가면으로 해체하여 현대 미술의 출발을 알린 기념비적 작품."},
    {"id": "a8_17", "level": 8, "term": "조르주브라크", "definition": "피카소와 함께 큐비즘을 창안하고 콜라주 기법을 최초로 도입하여 형태를 정밀하게 분석한 화가."},
    {"id": "a8_18", "level": 8, "term": "표현주의미술", "definition": "외부 사물의 객관적 모사가 아니라 화가의 내면에 도사린 불안, 공포, 소외감을 격렬하게 왜곡해 그림."},
    {"id": "a8_19", "level": 8, "term": "뭉크", "definition": "핏빛 노을 아래 다리 위에서 귀를 막고 비명을 지르는 인간의 근원적 실존 불안을 그린 '절규'의 화가."},
    {"id": "a8_20", "level": 8, "term": "절규", "definition": "일렁이는 곡선과 유령 같은 인물의 표정으로 세기말 인간의 극심한 공황과 고독을 시각화한 명작."},
    {"id": "a8_21", "level": 8, "term": "추상미술", "definition": "자연 대상을 구체적으로 묘사하지 않고 순수한 점, 선, 면, 색채의 자율적 조화만으로 구성한 예술."},
    {"id": "a8_22", "level": 8, "term": "칸딘스키", "definition": "음악을 들으며 색채와 형태가 영혼의 진동을 일으킨다고 본 서정적 추상(뜨거운 추상)의 아버지."},
    {"id": "a8_23", "level": 8, "term": "몬드리안", "definition": "수직선, 수평선과 빨강, 파랑, 노랑의 삼원색만으로 우주의 절대적 질서를 추구한 기하학적 추상(차가운 추상)."},
    {"id": "a8_24", "level": 8, "term": "신조형주의", "definition": "몬드리안이 주도한 더 스테일 운동으로 자연의 우연성을 배제하고 보편적 조화를 건축과 회화에 구현함."},
    {"id": "a8_25", "level": 8, "term": "말레비치", "definition": "흰 캔버스 위에 오직 검은 정사각형 하나만을 올려놓아 형태의 극단적 순수성을 선언한 '절대주의' 화가."},
    {"id": "a8_26", "level": 8, "term": "미래파", "definition": "과거의 미술관을 파괴하고 자동차, 비행기, 기계 문명의 빠른 속도감과 소음을 화폭에 찬양한 이탈리아 사조."},
    {"id": "a8_27", "level": 8, "term": "청기사파", "definition": "칸딘스키와 프란츠 마르크가 뮌헨에서 결성하여 예술의 정신적 가치와 신비주의를 추구한 예술가 그룹."},
    {"id": "a8_28", "level": 8, "term": "다리파", "definition": "키르히너 등이 드레스덴에서 결성하여 원시주의적 목판화 기법과 왜곡된 인체로 도시의 타락을 비판함."},
    {"id": "a8_29", "level": 8, "term": "소냐들로네", "definition": "남편 로베르 들로네와 함께 빛과 색채의 원형 프리즘이 교차하는 음악적 추상인 '오르피즘'을 창시함."},
    {"id": "a8_30", "level": 8, "term": "구성주의", "definition": "러시아 혁명기 타틀린 등이 철, 유리, 플라스틱 등 산업 재료를 이용해 사회주의 사회 건설에 복무한 미술."},
    {"id": "a8_31", "level": 8, "term": "타틀린", "definition": "유리와 철골 구조물이 나선형으로 회전하는 '제3인터내셔널 기념탑' 모델을 설계한 러시아 구성주의 거장."},

    # Lv.9 (+21)
    {"id": "a9_11", "level": 9, "term": "마르셀뒤샹", "definition": "남자용 소변기에 'R. Mutt 1917'이라고 서명하고 '샘'이라 이름 붙여 현대 개념 미술의 혁명을 일으킴."},
    {"id": "a9_12", "level": 9, "term": "샘", "definition": "미술은 손으로 만드는 기술이 아니라 작가의 '선택과 아이디어'라는 인식의 대전환을 가져온 뒤샹의 변기."},
    {"id": "a9_13", "level": 9, "term": "한스아르프", "definition": "종이 조각을 공중에 던져 바닥에 우연히 떨어진 배열 그대로 풀로 붙인 우연의 법칙 콜라주 화가."},
    {"id": "a9_14", "level": 9, "term": "초현실주의", "definition": "프로이트의 정신분석학에 영감을 받아 꿈, 무의식, 욕망의 환상적 세계를 사실적으로 묘사한 사조."},
    {"id": "a9_15", "level": 9, "term": "살바도르달리", "definition": "녹아내리는 시계, 바닷가의 기괴한 괴물 등 환각적 이미지를 편집광적 비판 기법으로 그린 초현실주의 거장."},
    {"id": "a9_16", "level": 9, "term": "기억의지속", "definition": "황량한 카탈루냐 해변 나뭇가지와 암석 위에 치즈처럼 축 늘어져 녹아내리는 회중시계들을 그린 달리의 대표작."},
    {"id": "a9_17", "level": 9, "term": "르네마그리트", "definition": "파이프 그림 밑에 '이것은 파이프가 아니다'라고 적어 이미지와 언어의 배반을 철학적으로 탐구한 벨기에 화가."},
    {"id": "a9_18", "level": 9, "term": "데페이즈망", "definition": "친숙한 사물을 엉뚱하고 낯선 장소에 배치하여 관람자의 일상적 상식과 고정관념에 충격을 주는 기법."},
    {"id": "a9_19", "level": 9, "term": "막스에른스트", "definition": "우연히 긁힌 무늬나 나뭇결에서 환상적 형상을 찾아내는 프로타주와 그라타주 기법을 창안한 화가."},
    {"id": "a9_20", "level": 9, "term": "호안미로", "definition": "어린아이의 낙서처럼 순수하고 생명력 넘치는 기호와 아메바 같은 유기적 형태를 유쾌하게 그린 화가."},
    {"id": "a9_21", "level": 9, "term": "프리다칼로", "definition": "참혹한 버스 교통사고의 육체적 고통과 디에고 리베라와의 상처를 강렬한 자화상으로 승화시킨 멕시코 화가."},
    {"id": "a9_22", "level": 9, "term": "오펜하임", "definition": "찻잔, 찻받침, 숟가락에 가젤의 부드러운 모피 털을 씌워 기괴한 촉각적 당혹감을 안겨준 오브제 작가."},
    {"id": "a9_23", "level": 9, "term": "키리코", "definition": "햇빛이 강하게 내리쬐지만 인적이 끊긴 텅 빈 광장과 긴 그림자로 서늘한 불안감을 주는 형이상학적 회화 창시자."},
    {"id": "a9_24", "level": 9, "term": "앙드레브르통", "definition": "'초현실주의 선언'을 발표하여 이성의 감시에서 벗어난 무의식의 받아쓰기(오토마티슴)를 주창한 문학가."},
    {"id": "a9_25", "level": 9, "term": "오토마티슴", "definition": "사전 구상 없이 무의식의 흐름에 손을 맡겨 붓이나 펜을 저절로 움직이게 하는 자동기술법."},
    {"id": "a9_26", "level": 9, "term": "알베르토자코메티", "definition": "군더더기 살점을 모두 깎아내고 철사처럼 앙상하게 뼈대만 남은 인물이 홀로 걸어가는 실존주의 조각가."},
    {"id": "a9_27", "level": 9, "term": "헨리무어", "definition": "자연의 돌과 뼈에서 영감을 받아 인체의 부드러운 곡선과 구멍 뚫린 공간의 조화를 탐구한 영국 조각가."},
    {"id": "a9_28", "level": 9, "term": "만레이", "definition": "카메라 렌즈 없이 감광지 위에 사물을 올려놓고 빛을 비추어 실루엣을 만드는 레이오그래프 창안자."},
    {"id": "a9_29", "level": 9, "term": "콜비츠", "definition": "가난한 노동자와 전쟁으로 자식을 잃은 어머니들의 비통한 슬픔을 흑백 판화로 고발한 독일 판화가."},
    {"id": "a9_30", "level": 9, "term": "샤갈", "definition": "고향 러시아 마을의 추억과 연인들의 사랑을 하늘을 나는 환상적인 색채 동화로 노래한 거장."},
    {"id": "a9_31", "level": 9, "term": "멕시코벽화", "definition": "디에고 리베라, 오로스코 등이 공공건물 벽에 민중 혁명과 인디언 역사를 웅장하게 그린 사회주의 미술."},

    # Lv.10 (+21)
    {"id": "a10_11", "level": 10, "term": "추상표현주의", "definition": "2차 대전 후 세계 미술의 중심이 파리에서 뉴욕으로 이동하며 탄생한 거대 스케일의 전위 추상 미술."},
    {"id": "a10_12", "level": 10, "term": "잭슨폴록", "definition": "캔버스를 바닥에 눕혀놓고 그 주위를 춤추듯 돌며 페인트를 뿌리고 흘리는 '액션 페인팅'의 창시자."},
    {"id": "a10_13", "level": 10, "term": "액션페인팅", "definition": "완성된 결과물보다 캔버스 위에서 몸을 움직이며 물감을 떨어뜨리는 행위 자체를 중시하는 기법(드리핑)."},
    {"id": "a10_14", "level": 10, "term": "올오버페인팅", "definition": "화면의 중심이나 위계 없이 캔버스 전체가 균등한 에너지의 그물망으로 채워지는 전면 균질 회화."},
    {"id": "a10_15", "level": 10, "term": "마크로스코", "definition": "거대한 캔버스 위에 경계가 번지는 단색의 색면 블록을 띄워 숭고한 침묵과 눈물의 영성을 자아낸 화가."},
    {"id": "a10_16", "level": 10, "term": "색면회화", "definition": "넓고 평평한 색채의 면 자체를 탐구하여 관람자가 거대한 색채 속에 온몸이 잠겨들게 만드는 회화."},
    {"id": "a10_17", "level": 10, "term": "앤디워홀", "definition": "수프 깡통과 마릴린 먼로를 '팩토리'에서 실크스크린으로 대량 인쇄하여 예술과 상업의 경계를 허문 팝아트 제왕."},
    {"id": "a10_18", "level": 10, "term": "로이리히텐슈타인", "definition": "만화의 한 장면을 확대하고 인쇄 망점(벤데이 도트)과 말풍선까지 정밀하게 화폭에 옮겨 그린 팝아트 화가."},
    {"id": "a10_19", "level": 10, "term": "미니멀아트", "definition": "작가의 개성이나 주관적 감정을 극도로 배제하고 단순한 기하학적 철제 상자나 볼륨만을 반복 제시함."},
    {"id": "a10_20", "level": 10, "term": "도널드저드", "definition": "벽면에 일정한 간격으로 금속과 아크릴 상자를 층층이 설치하여 조각도 회화도 아닌 '특수한 대상'을 제시함."},
